use CW\Matching\StoredBand;
use CW\Matching\Text;
use CW\Matching\TitlePattern;
use CW\Matching\Veto;

$pass = 0;
$fail = 0;
$failures = [];
function t(string $name, callable $fn): void
{
    global $pass, $fail, $failures;
    try {
        $fn();
        $pass++;
    } catch (Throwable $e) {
        $fail++;
        $failures[] = "FAIL $name: " . $e->getMessage();
    }
}
function ok(bool $c, string $msg = 'assertion failed'): void
{
    if (!$c) {
        throw new RuntimeException($msg);
    }
}
function eq(mixed $a, mixed $b, string $msg = ''): void
{
    if ($a !== $b) {
        throw new RuntimeException(($msg !== '' ? "$msg: " : '') . 'expected ' . json_encode($b) . ', got ' . json_encode($a));
    }
}
function row(array $o): array
{
    return $o + [
        'site' => 'test', 'variant_id' => 1, 'product_id' => 1, 'product_title' => '', 'variant_title' => '', 'brand' => '',
        'product_type' => 'simple', 'variant_status' => 'Published', 'is_landing' => 0, 'is_default' => 1, 'price' => 4.99,
        'sale_price' => null, 'barcodes' => [], 'attributes' => [], 'units_30d' => 0, 'units_365d' => 0,
    ];
}
function N(array $o, array $ctx = []): array
{
    return Normalizer::normalize(row($o), $ctx);
}
function attr(string $name, string $value, int $var = 0): array
{
    return ['attr_id' => 0, 'name' => $name, 'value' => $value, 'is_variable' => $var];
}
function codes(array $res): array
{
    return array_values(array_unique(array_column($res['vetoes'], 'code')));
}

// ───────────────────────────── fixture ─────────────────────────────
$fx = json_decode((string) file_get_contents(__DIR__ . '/../fixtures/matching/golden_listings.json'), true, 512, JSON_BIGINT_AS_STRING);
function F(string $site, int $id): array
{
    global $fx;
    $r = $fx['rows'][$site][(string) $id] ?? null;
    if ($r === null) {
        throw new RuntimeException("fixture missing $site#$id");
    }
    $f = Normalizer::normalize($r, $fx['ctx'][$site][(string) $id]);
    $f['product_live'] = ($r['product_status'] ?? '') === 'Published';
    return $f;
}
function A(int $id): array
{
    return F('electrofag', $id);
}
function V(int $id): array
{
    return F('vapeandgo', $id);
}
function R(string $site, int $id): array
{
    global $fx;
    return $fx['rows'][$site][(string) $id];
}
/** Veto a real ALT listing against a real VPG item (seed context taken from the fixture row). */
function pair(int $aid, int $vid): array
{
    $v = R('vapeandgo', $vid);
    $inSeed = ($v['variant_status'] ?? '') === 'Published' && (int) $v['is_landing'] === 0;
    return Veto::check(A($aid), V($vid), 1, ['s_in_seed' => $inSeed, 's_product_published' => ($v['product_status'] ?? '') === 'Published']);
}
/** Best band this pair can EVER reach as a barcode-lane pair, with a judge that agrees at confidence 100. */
function bestBand(int $aid, int $vid, string $lane = 'barcode'): string
{
    $res = pair($aid, $vid);
    $ev = ['lane' => $lane, 'target' => $vid, 'target_vetoes' => $res['vetoes'], 'target_flags' => $res['flags'],
        'candidates' => [['id' => $vid, 'prescore' => 100, 'vetoes' => $res['vetoes']]]];
    return Band::final($ev, ['outcome' => 'match', 'chosen_id' => $vid, 'confidence' => 100, 'units_per_item' => 1])['band'];
}
function trap(int $aid, int $vid, string $expectVeto = null): void
{
    $res = pair($aid, $vid);
    if ($expectVeto !== null) {
        ok(in_array($expectVeto, codes($res), true), "A#$aid vs V#$vid: expected veto $expectVeto, got " . json_encode(codes($res)) . ' flags ' . json_encode($res['flags']));
    }
    $b = bestBand($aid, $vid);
    ok($b !== Band::KEY, "A#$aid vs V#$vid banded Key");
}
function truePair(int $aid, int $vid): array
{
    $res = pair($aid, $vid);
    ok($res['vetoes'] === [], "A#$aid vs V#$vid must not be vetoed, got " . json_encode($res['vetoes']));
    return $res;
}

