// ═════════════════════════════ 2 Gtin / Band / JudgeCard / Flavour units ═════════════════════════════
t('gtin check digit and keys', function () {
    ok(Gtin::checkDigitOk('5056168878109'));
    ok(!Gtin::checkDigitOk('5056168878108'));
    ok(Gtin::checkDigitOk('34966440488'), 'UPC-A with its leading zero dropped');
    eq(Gtin::key('06943498697557'), '6943498697557');
    eq(Gtin::key(6943498697557), '6943498697557');
    eq(Gtin::classify('1746')['usable'], false);
    eq(Gtin::classify('1746')['reason'], 'too_short');
    eq(Gtin::classify('5056168878108')['reason'], 'bad_check_digit');
    eq(Gtin::classify('5056168878109')['usable'], true);
    $idx = Gtin::index([1 => ['06943498697557'], 2 => [6943498697557], 3 => [5056168878109]]);
    ok(isset($idx['multi']['6943498697557']), 'same code on two items is flagged');
    ok(!isset($idx['multi']['5056168878109']));
});
t('band: provisional', function () {
    eq(Band::provisional(['lane' => 'ignore', 'is_placeholder' => true])['band'], Band::IGNORE);
    eq(Band::provisional(['lane' => 'barcode', 'flags' => ['multi_sku_gtin']])['band'], Band::CONFLICT);
    eq(Band::provisional(['lane' => 'barcode', 'target' => 5, 'target_vetoes' => [['code' => 'strength']]])['band'], Band::CONFLICT);
    $p = Band::provisional(['lane' => 'barcode', 'target' => 5, 'target_vetoes' => [], 'target_flags' => []]);
    eq([$p['band'], $p['ceiling']], [null, Band::KEY]);
    eq(Band::provisional(['lane' => 'barcode', 'target' => 5, 'target_vetoes' => [], 'target_flags' => ['price_outlier']])['ceiling'], Band::CHECK);
    eq(Band::provisional(['lane' => 'candidates', 'candidates' => []])['ceiling'], Band::NEW_ITEM);
    eq(Band::provisional(['lane' => 'candidates', 'candidates' => [['id' => 1, 'prescore' => 50, 'vetoes' => []]]])['ceiling'], Band::NEW_ITEM);
    eq(Band::provisional(['lane' => 'candidates', 'candidates' => [['id' => 1, 'prescore' => 80, 'vetoes' => []]], 'separating_field_missing' => 'strength'])['ceiling'], Band::CANT_TELL);
    eq(Band::provisional(['lane' => 'candidates', 'candidates' => [['id' => 1, 'prescore' => 80, 'vetoes' => []]]])['ceiling'], Band::CHECK);
});
t('band: final with a judge', function () {
    $key = ['lane' => 'barcode', 'target' => 7, 'target_vetoes' => [], 'target_flags' => [], 'candidates' => [['id' => 7, 'prescore' => 90, 'vetoes' => []], ['id' => 8, 'prescore' => 70, 'vetoes' => []]]];
    eq(Band::final($key, ['outcome' => 'match', 'chosen_id' => 7, 'confidence' => 95, 'units_per_item' => 1])['band'], Band::KEY);
    eq(Band::final($key, ['outcome' => 'match', 'chosen_id' => 7, 'confidence' => 80, 'units_per_item' => 1])['band'], Band::CHECK);
    eq(Band::final($key, ['outcome' => 'match', 'chosen_id' => 7, 'confidence' => 95, 'units_per_item' => 2])['band'], Band::CHECK);
    eq(Band::final($key, ['outcome' => 'match', 'chosen_id' => 8, 'confidence' => 90, 'units_per_item' => 1])['band'], Band::CONFLICT);
    eq(Band::final($key, ['outcome' => 'no_match_in_list', 'chosen_id' => null, 'confidence' => 85, 'units_per_item' => null])['band'], Band::CONFLICT);
    eq(Band::final($key, ['outcome' => 'cannot_tell', 'chosen_id' => null, 'confidence' => 60, 'units_per_item' => null])['band'], Band::CANT_TELL);
    $open = ['lane' => 'candidates', 'candidates' => [['id' => 1, 'prescore' => 50, 'vetoes' => []], ['id' => 2, 'prescore' => 95, 'vetoes' => [['code' => 'strength']]]]];
    eq(Band::final($open, ['outcome' => 'no_match_in_list', 'chosen_id' => null, 'confidence' => 95, 'units_per_item' => null])['band'], Band::NEW_ITEM);
    eq(Band::final($open, ['outcome' => 'match', 'chosen_id' => 2, 'confidence' => 99, 'units_per_item' => 1])['band'], Band::CONFLICT, 'AI match on a vetoed pair');
    eq(Band::final($open, ['outcome' => 'match', 'chosen_id' => 1, 'confidence' => 90, 'units_per_item' => 1])['band'], Band::CHECK, 'AI only is at most Check');
});
t('judge card is barcode-blind', function () {
    $r = R('electrofag', 7409);
    $f = A(7409);
    $c = JudgeCard::card('L1', $r, $f);
    eq(array_keys($c), JudgeCard::CORE_FIELDS);
    JudgeCard::assertBlind(['items' => [['ref' => 'L1', 'listing' => $c]]], array_map('strval', $r['barcodes']));
    $threw = false;
    try {
        JudgeCard::assertBlind(['items' => [['ref' => 'L1', 'listing' => $c + ['barcodes' => $r['barcodes']]]]], []);
    } catch (RuntimeException) {
        $threw = true;
    }
    ok($threw, 'a barcode field must be refused');
    eq(JudgeCard::mask('Code 5056168878109 inside'), 'Code [number] inside');
});
