t('trap: distributor brand ("Vapes Bars" selling PIXL) is blocked by title family, not aliased 1:1', function () {
    $a = A(6597);
    eq($a['brand_family'], ['bars']);
    $res = truePair(6597, 37353);
    eq($res['fields']['brand_line'], 'agree', 'brand/line agrees through the title');
