/** A trap that must carry this soft flag (and so can never reach Key). */
function flagged(int $aid, int $vid, string $flag): array
{
    $res = pair($aid, $vid);
    ok(in_array($flag, $res['flags'], true), "A#$aid vs V#$vid: expected flag $flag, got flags " . json_encode($res['flags']) . ' vetoes ' . json_encode(codes($res)));
    ok(bestBand($aid, $vid) !== Band::KEY, "A#$aid vs V#$vid banded Key");
    return $res;
}
/** A true pair that stays clean enough to reach Key with an agreeing judge. */
function keyPair(int $aid, int $vid): void
{
    truePair($aid, $vid);
    eq(bestBand($aid, $vid), Band::KEY, "A#$aid vs V#$vid best band");
}

